  "id": "local-risks",
  "type": "risk",
  "title": "Local-only: risks",
  "text": "The largest risk is unrecoverable loss when a device is lost, damaged, reset, or corrupted. Users must understand and use export or backup features. Moving between devices is inconvenient, and concurrent use across devices is impractical. Local data should still be encrypted where the platform permits, with careful key handling and migration testing.",
  "data": {
    "severity": "High if backup is omitted",
    "mitigation": "Provide encrypted export/import, backup reminders, atomic writes, schema migrations, and recovery testing."
  }
}

details.after:
{
  "parent": null,
  "index": 3,
  "id": "local-risks",
  "type": "risk",
  "title": "Local-only: risks",
  "text": "With seamless phone-and-laptop access required at launch, local-only is not just inconvenient across devices; it fails a stated launch requirement unless a sync mechanism is added. Its remaining major risk is unrecoverable loss when a device is lost, damaged, reset, or corrupted. Mitigate with encrypted export/import, backup reminders, atomic writes, schema migrations, recovery testing, and platform-appropriate encryption.",
  "data": {
    "severity": "High if backup is omitted",
    "mitigation": "Encrypted export/import, backup reminders, atomic writes, schema migrations, recovery testing, and platform-appropriate encryption still reduce loss risk, but they do not provide seamless cross-device access."
  }
}

details.before:
{
  "parent": null,
  "index": 5,
  "id": "cloud-risks",
  "type": "risk",
  "title": "Cloud sync: risks",
  "text": "Financial records become a high-value remote target. The product must handle authentication, authorization, encryption, retention, deletion, incident response, and account recovery. Sync introduces duplicate, stale, and conflicting edits that can silently damage user trust. Availability and recurring infrastructure costs become product concerns.",
  "data": {
    "severity": "High",
    "mitigation": "Use a mature identity provider, least-privilege access, encryption, auditable deletion, conflict-safe data modeling, idempotent sync, monitoring, and tested restore procedures."
  }
}

details.after:
{
  "parent": null,
  "index": 5,
  "id": "cloud-risks",
  "type": "risk",
  "title": "Cloud sync: risks",
  "text": "Cloud sync is now required to satisfy launch scope, so its security and operational risks are accepted responsibilities rather than optional future complexity. Financial records become a high-value remote target, and sync can introduce duplicate, stale, or conflicting edits that damage user trust. Authentication, authorization, encryption, retention, deletion, incident response, account recovery, availability, and cost all become product concerns.",
  "data": {
    "severity": "High",
    "mitigation": "Use a mature identity provider, least-privilege access, encryption, auditable deletion, conflict-safe data modeling, idempotent sync, clear offline/online semantics, monitoring, cost controls, and tested restore and account-recovery procedures."
  }
}

details.before:
{
  "parent": null,
  "index": 6,
  "id": "recommendation",
  "type": "callout",
  "title": "Recommendation",
  "text": "Start with local-only storage, paired with encrypted export/import and clear backup guidance. For a personal tracker, this delivers the core value with the smallest privacy, security, and operational burden. Design stable record identifiers and timestamps now so cloud sync can be added later if validated demand for seamless multi-device use outweighs the added responsibility. Choose cloud sync now only if cross-device continuity is a launch requirement rather than a future convenience.",
  "data": {
    "status": "Recommended: local-only first"
  }
}

details.after:
